import os,sys,json,pathlib,subprocess,signal,time,hashlib,importlib.util,hmac,base64,secrets
P=pathlib.Path;ROOT=P('/Users/sondre/Documents/GitHub/voxl-desktop-native-validation')
SOURCE=sys.argv[1];OUT=P(sys.argv[2]);CASES=[x for x in sys.argv[3:]if x!='--inside-lock'];INNER='--inside-lock'in sys.argv
OUT.mkdir(mode=0o700,exist_ok=True);os.umask(0o077)
ENV=os.environ|{'DEVELOPER_DIR':'/Applications/Xcode-beta.app/Contents/Developer','CARGO_TARGET_DIR':str(ROOT/'media/target'),'CARGO_BUILD_WARNINGS':'deny','CI':'true','CARGO_BUILD_JOBS':'2'}
steps=[];turns=[];children=[];private=[];terminal=False;result=1
def digest(path):return hashlib.sha256(P(path).read_bytes()).hexdigest()
def interrupted(signum,frame):raise KeyboardInterrupt()
signal.signal(signal.SIGTERM,interrupted);signal.signal(signal.SIGINT,interrupted)
def gone(group):
 try:os.killpg(group,0);return False
 except ProcessLookupError:return True
def stop(child):
 if not gone(child.pid):
  try:os.killpg(child.pid,signal.SIGTERM)
  except ProcessLookupError:pass
 try:child.wait(timeout=4)
 except subprocess.TimeoutExpired:
  try:os.killpg(child.pid,signal.SIGKILL)
  except ProcessLookupError:pass
  child.wait(timeout=3)
 if not gone(child.pid):
  try:os.killpg(child.pid,signal.SIGKILL)
  except ProcessLookupError:pass
def verify():
 assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True,timeout=10).strip()==SOURCE
 assert not subprocess.check_output(['git','status','--porcelain'],cwd=ROOT,text=True,timeout=10).strip()
def save():
 value={'source':SOURCE,'root':str(ROOT),'terminal':terminal,'exitCode':result if terminal else None,'helperSha256':digest(__file__),'steps':steps,'turns':turns,'limits':'Local UDP/DTLS/SRTP with synthetic NALs and isolated coturn. No native capture/decoder, physical devices/network, UI, CPU/RAM saving or bandwidth/quality qualification.'}
 (OUT/('results.json'if INNER else'queue.json')).write_text(json.dumps(value,indent=2)+'\n')
def run(name,command,deadline,extra=None,check=True):
 if check:verify()
 started=time.monotonic();path=OUT/(name+'.log')
 with path.open('x')as log:
  child=subprocess.Popen(command,cwd=ROOT,env=ENV|dict(extra or {}),stdout=log,stderr=subprocess.STDOUT,start_new_session=True);children.append(child)
  if INNER:(OUT/'active-group.json').write_text(json.dumps({'pgid':child.pid}))
  try:code=child.wait(timeout=deadline)
  except subprocess.TimeoutExpired:stop(child);code=124
  except BaseException:stop(child);raise
  finally:
   stop(child)
   if INNER:(OUT/'active-group.json').unlink(missing_ok=True)
 if check:verify()
 raw=path.read_text(errors='replace')
 assert not any(secret in raw for secret in private),'private fixture credential in child output'
 steps.append({'name':name,'command':command,'deadlineSeconds':deadline,'exitCode':code,'childExitCode':child.returncode,'seconds':round(time.monotonic()-started,3),'pgid':child.pid,'groupGone':gone(child.pid),'logSha256':digest(path)});save();print(name,code,flush=True)
 assert gone(child.pid)
 return code
try:
 if not INNER:
  assert not subprocess.check_output(['git','status','--porcelain'],cwd=ROOT,text=True,timeout=10).strip()
  assert run('fetch',['git','fetch','origin','fincode/desktop-streaming'],30,check=False)==0
  assert run('detach',['git','switch','--detach',SOURCE],15,check=False)==0
  verify();result=run('queue',['/usr/bin/lockf','-k','-t','45','/tmp/fincode-build.lock','/usr/bin/nice','-n','19',sys.executable,__file__,SOURCE,str(OUT),*CASES,'--inside-lock'],1500)
 else:
  verify();assert run('load',['/usr/bin/uptime'],10)==0;assert run('toolchain',['cargo','--version'],10)==0
  base=['--locked','--manifest-path','media/Cargo.toml','--features','webrtc','--lib','-j2','-q']
  code=run('build',['cargo','test',*base,'--no-run','--message-format=json'],900)
  if code:result=code;raise SystemExit(code)
  records=[json.loads(x)for x in(OUT/'build.log').read_text().splitlines()if x.startswith('{')]
  artifacts=[x for x in records if x.get('reason')=='compiler-artifact'and x.get('target',{}).get('name')=='voxl_media'and x.get('executable')];assert len(artifacts)==1
  executable=P(artifacts[0]['executable']);assert executable.parent==ROOT/'media/target/debug/deps'
  (OUT/'build-selection.json').write_text(json.dumps({'artifact':artifacts[0],'executableSha256':digest(executable),'fullLogSha256':digest(OUT/'build.log')},indent=2)+'\n')
  code=run('clippy',['cargo','clippy',*base,'--tests','--examples','--message-format=short','--','-D','warnings'],300)
  if code:result=code;raise SystemExit(code)
  spec=importlib.util.spec_from_file_location('owned_turn',OUT/'turn-fixture.py');module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
  result=0
  for index,case in enumerate(CASES):
   if case.startswith('unit:'):
    full=case.removeprefix('unit:');name=full.rsplit('::',1)[1]
    code=run(name,[str(executable),'--exact',full,'--nocapture'],15);result=code
    if code:break
    assert '1 passed; 0 failed; 0 ignored;'in(OUT/(name+'.log')).read_text()
    continue
   turn=module.TurnFixture(OUT/('private-turn-'+str(index)));turn.start()
   alternate=str(turn.expires)+':'+secrets.token_hex(8);password=base64.b64encode(hmac.new(turn.secret.encode(),alternate.encode(),hashlib.sha1).digest()).decode()
   private.extend([turn.secret,turn.username,turn.password,alternate,password])
   env={'VOXL_TEST_TURN_UDP':turn.credentials()['urls'][0],'VOXL_TEST_TURN_USERNAME':turn.username,'VOXL_TEST_TURN_PASSWORD':turn.password,'VOXL_TEST_TURN_ALTERNATE_USERNAME':alternate,'VOXL_TEST_TURN_ALTERNATE_PASSWORD':password}
   try:
    code=run(case,[str(executable),'--ignored','--exact','webrtc::tests::live_restart::'+case,'--nocapture'],35,env);result=code
   finally:
    summary=turn.close();summary|={'case':case,'pgid':turn.process.pid,'privateLogSha256':digest(turn.root/'server-private.log'),'fixtureHelperSha256':digest(OUT/'turn-fixture.py')};turns.append(summary);turn.config.unlink(missing_ok=True);save()
   if code:result=code;break
   assert '1 passed; 0 failed; 0 ignored;'in(OUT/(case+'.log')).read_text()
   if case=='live_automatic_restart_skips_unused_relay_allocations':assert summary['successfulAllocations']==0
except BaseException:
 result=result or 1
 raise
finally:
 for child in reversed(children):stop(child)
 if not INNER:
  path=OUT/'active-group.json'
  if path.exists():
   group=json.loads(path.read_text())['pgid']
   if not gone(group):os.killpg(group,signal.SIGKILL)
 terminal=True;save()
raise SystemExit(result)

import pathlib,subprocess,socket,secrets,time,os,signal,threading,json,hashlib,hmac,base64,struct,re

class TurnFixture:
    def __init__(self,root):
        self.root=pathlib.Path(root);self.root.mkdir(mode=0o700,exist_ok=False)
        self.process=None;self.timer=None;self.stream=None;self.ready=False
        self.secret=secrets.token_hex(32)
        self.expires=int(time.time())+600
        self.username=str(self.expires)+':'+secrets.token_hex(8)
        self.password=base64.b64encode(hmac.new(self.secret.encode(),self.username.encode(),hashlib.sha1).digest()).decode()
        with socket.socket(socket.AF_INET,socket.SOCK_DGRAM) as probe:
            probe.bind(('127.0.0.1',0));self.port=probe.getsockname()[1]
        for _ in range(30):
            base=40000+secrets.randbelow(20000-16);sockets=[]
            try:
                for port in range(base,base+16):
                    s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);sockets.append(s);s.bind(('127.0.0.1',port))
                self.relay_ports=list(range(base,base+16));break
            except OSError:pass
            finally:
                for s in sockets:s.close()
        else:raise RuntimeError('no owned relay port range available')
        interfaces=subprocess.check_output(['/sbin/ifconfig'],text=True,timeout=10)
        addresses=set(re.findall(r'\binet\s+(\d+\.\d+\.\d+\.\d+)',interfaces))|{'127.0.0.1'}
        options=['listening-ip=127.0.0.1','relay-ip=127.0.0.1','listening-port='+str(self.port),
            'min-port='+str(self.relay_ports[0]),'max-port='+str(self.relay_ports[-1]),
            'realm=fincode-fixture.invalid','use-auth-secret','static-auth-secret='+self.secret,
            'no-auth-pings','no-dynamic-ip-list','no-dynamic-realms','no-tcp','no-tls','no-tcp-relay',
            'relay-threads=0','cpus=1','allow-loopback-peers','no-multicast-peers',
            'denied-peer-ip=0.0.0.0-255.255.255.255','denied-peer-ip=::-ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff',
            'max-allocate-lifetime=300','total-quota=8','user-quota=4','max-bps=5000000','bps-capacity=20000000',
            'pidfile='+str(self.root/'server.pid'),'userdb='+str(self.root/'server.sqlite'),
            'log-file=stdout','simple-log','verbose']+['allowed-peer-ip='+ip for ip in sorted(addresses)]
        self.config=self.root/'server.conf';self.config.write_text('\n'.join(options)+'\n');self.config.chmod(0o600)
    def credentials(self):
        return {'urls':['turn:127.0.0.1:'+str(self.port)+'?transport=udp'],'username':self.username,
            'credential':self.password,'expires_at_millis':self.expires*1000}
    def start(self):
        self.stream=(self.root/'server-private.log').open('w');os.chmod(self.root/'server-private.log',0o600)
        self.process=subprocess.Popen(['/opt/homebrew/opt/coturn/bin/turnserver','-c',str(self.config)],
            stdout=self.stream,stderr=subprocess.STDOUT,start_new_session=True)
        self.timer=threading.Timer(360,self.terminate);self.timer.start()
        transaction=secrets.token_bytes(12);request=struct.pack('!HHI',1,0,0x2112a442)+transaction
        with socket.socket(socket.AF_INET,socket.SOCK_DGRAM) as client:
            client.settimeout(.25);deadline=time.monotonic()+8
            while time.monotonic()<deadline and self.process.poll() is None:
                client.sendto(request,('127.0.0.1',self.port))
                try:
                    data,_=client.recvfrom(2048)
                    if data[:2]==b'\x01\x01' and data[8:20]==transaction:self.ready=True;return
                except socket.timeout:pass
        raise RuntimeError('owned TURN listener not ready')
    def terminate(self):
        p=self.process
        if p is None or p.poll() is not None:return
        try:os.killpg(p.pid,signal.SIGTERM)
        except ProcessLookupError:pass
        try:p.wait(timeout=4)
        except subprocess.TimeoutExpired:
            if p.poll() is None:
                try:os.killpg(p.pid,signal.SIGKILL)
                except ProcessLookupError:pass
                except PermissionError:
                    # Do not suppress refusal for a still-live owned server.
                    p.wait(timeout=3)
            p.wait(timeout=3)
    def close(self):
        if self.timer is not None:self.timer.cancel()
        self.terminate()
        if self.timer is not None:self.timer.join()
        if self.stream is not None:self.stream.close()
        ports=[self.port]+self.relay_ports
        for port in ports:
            with socket.socket(socket.AF_INET,socket.SOCK_DGRAM) as probe:probe.bind(('127.0.0.1',port))
        groups=subprocess.check_output(['ps','-axo','pgid='],text=True,timeout=10).splitlines()
        gone=self.process is None or all(int(row.strip())!=self.process.pid for row in groups if row.strip())
        assert gone
        data=(self.root/'server-private.log').read_text(errors='replace') if self.stream is not None else ''
        counts={name:len(re.findall(pattern,data)) for name,pattern in {
            'successfulAllocations':r'ALLOCATE processed, success',
            'successfulPermissions':r'CREATE_PERMISSION processed, success',
            'successfulChannelBindings':r'CHANNEL_BIND processed, success',
            'usageRows':r'usage:.*?rp=\d+.*?rb=\d+.*?sp=\d+.*?sb=\d+'}.items()}
        result={'ready':self.ready,'exit':None if self.process is None else self.process.returncode,
            'groupGone':gone,'allOwnedUDPPortsRebound':True,'ownedPortCount':len(ports),**counts}
        (self.root/'public-summary.json').write_text(json.dumps(result,indent=2)+'\n')
        return result

